-- Shared, offline presentation for the two Anki note types. No schema changes.
local Design = {}
Design.css = [[.card{--bg:#fafaf7;--fg:#242b2a;--muted:#626c68;--accent:#24695b;--line:#dce2dc;--soft:#eff2ec;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:21px;line-height:1.65;text-align:left;color:var(--fg);background:var(--bg);margin:0;padding:28px 20px;overflow-wrap:anywhere;-webkit-text-size-adjust:100%}.study{max-width:640px;margin:20px auto 48px}.eyebrow{font-size:12px;line-height:1.5;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin:0 0 24px}.question{font-size:27px;line-height:1.45;font-weight:600;white-space:pre-wrap}.answer{font-size:25px;line-height:1.55;font-weight:600;color:var(--accent);border-top:1px solid var(--line);margin-top:24px;padding-top:24px;white-space:pre-wrap}.definition{font-size:22px;line-height:1.55;white-space:pre-wrap}.word{font-size:34px;line-height:1.25;font-weight:650;margin:0 0 8px}.ipa{font-size:18px;color:var(--muted);margin-bottom:24px}.sentence{font-size:24px;line-height:1.65;margin:24px 0;padding:18px 20px;background:var(--soft);border-radius:10px}.cloze{font-weight:650;color:var(--accent)}.synonyms{font-size:17px;color:var(--muted);margin:14px 0}.explanation{font-size:20px;margin:22px 0;white-space:pre-wrap}.media{text-align:center;margin:22px 0}.media img{max-width:100%;max-height:260px;width:auto;height:auto;object-fit:contain;border-radius:8px}.audio{margin:18px 0}.source{margin-top:30px;padding-top:20px;border-top:1px solid var(--line)}.source blockquote{font-size:18px;line-height:1.65;white-space:pre-wrap;margin:0 0 18px;padding:0 0 0 16px;border-left:2px solid var(--line)}.meta{font-size:15px;line-height:1.6;color:var(--muted);margin:4px 0}.source-link{display:inline-block;font-size:15px;margin-top:8px}a{color:var(--accent);text-decoration:underline;text-underline-offset:3px}details{margin-top:18px;font-size:17px;color:var(--muted)}summary{cursor:pointer;padding:8px 0}details .selection{white-space:pre-wrap;margin-top:10px;color:var(--fg)}.nightMode,.night_mode{--bg:#191d1c;--fg:#e7ebe6;--muted:#a5b0a9;--accent:#9bcfbc;--line:#39433e;--soft:#242d28}img{max-width:100%}hr#answer{border:0;border-top:1px solid var(--line)}@media(max-width:480px){.card{padding:20px 16px}.study{margin:12px auto 32px}.question{font-size:24px}.answer{font-size:23px}.word{font-size:30px}.sentence{font-size:22px;padding:16px}.eyebrow{margin-bottom:20px}}]]
function Design.vocabulary()
    return {css = Design.css, template = {Name = "Card 1",
        Front = [[<main class="study"><div class="eyebrow">Vocabulario · recuerda la expresión</div>{{#Definition}}<div class="definition">{{Definition}}</div>{{/Definition}}<div class="sentence">{{cloze:Text}}</div>{{#Synonyms}}<div class="synonyms">{{Synonyms}}</div>{{/Synonyms}}{{#ImageFront}}<div class="media">{{ImageFront}}</div>{{/ImageFront}}</main>]],
        Back = [[<main class="study"><div class="eyebrow">Vocabulario</div><div class="word">{{Phrase}}</div>{{#IPA}}<div class="ipa">{{IPA}}</div>{{/IPA}}{{#Definition}}<div class="definition">{{Definition}}</div>{{/Definition}}<div class="sentence">{{cloze:Text}}</div>{{#Synonyms}}<div class="synonyms">{{Synonyms}}</div>{{/Synonyms}}{{#ImageBack}}<div class="media">{{ImageBack}}</div>{{/ImageBack}}{{#Sound}}<div class="audio">{{Sound}}</div>{{/Sound}}{{#Source}}<div class="source"><a class="source-link" href="{{Source}}">Consultar fuente ↗</a></div>{{/Source}}</main>]]}}
end
function Design.learning()
    local css = Design.css .. [[.section-label{font-size:15px;font-weight:600;line-height:1.5;letter-spacing:.04em;color:var(--muted);margin:0 0 12px}.explanation-block{margin-top:36px}.explanation-block .explanation{margin:0}.study .source{margin-top:36px;padding-top:28px}]]
    return {css = css, template = {Name = "Pregunta",
        Front = [[<main class="study"><div class="eyebrow">Aprendizaje · recuerda la idea</div><div class="question">{{Question}}</div></main>]],
        Back = [[<main class="study"><div class="eyebrow">Aprendizaje</div><div class="question">{{Question}}</div><div class="answer" id="answer">{{Answer}}</div>{{#Explanation}}<section class="explanation-block"><h2 class="section-label">Explicación</h2><div class="explanation">{{Explanation}}</div></section>{{/Explanation}}<section class="source">{{#SourceExcerpt}}<h2 class="section-label">Cita del libro</h2><blockquote>{{SourceExcerpt}}</blockquote>{{/SourceExcerpt}}{{^SourceExcerpt}}{{#SelectedText}}<h2 class="section-label">Fragmento seleccionado</h2><blockquote>{{SelectedText}}</blockquote>{{/SelectedText}}{{/SourceExcerpt}}{{#BookTitle}}<div class="meta">{{BookTitle}}{{#Author}} · {{Author}}{{/Author}}</div>{{/BookTitle}}{{^BookTitle}}{{#Author}}<div class="meta">{{Author}}</div>{{/Author}}{{/BookTitle}}{{#Chapter}}<div class="meta">{{Chapter}}</div>{{/Chapter}}{{#Location}}<div class="meta">{{Location}}</div>{{/Location}}{{#SourceExcerpt}}{{#SelectedText}}<details><summary>Selección original</summary><div class="selection">{{SelectedText}}</div></details>{{/SelectedText}}{{/SourceExcerpt}}</section></main>]]}}
end
return Design
